#!/usr/bin/env python
"""
Test the exact scenario described in the PR description.
"""

import os
import sys
import django
from django.conf import settings

# Configure Django settings
if not settings.configured:
    settings.configure(
        DEBUG=True,
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'django.contrib.contenttypes',
            'django.contrib.auth',
        ],
        SECRET_KEY='test-secret-key',
    )

django.setup()

# This is the exact code from the PR description that was crashing
from django.db import models

f = models.CharField(max_length=200)
d = {f: 1}

class Book(models.Model):
    title = f

    class Meta:
        app_label = 'test'

# This assertion was failing before the fix
assert f in d

print("✅ Original issue is fixed! The field remains in the dictionary after model assignment.")
